<?php
if(PHP_SAPI!=='cli'||!isset($db,$work))exit;
if(!preg_match('/^tooltrack_test_[a-f0-9]{12}$/',(string)$db->query('SELECT DATABASE()')->fetchColumn()))throw new RuntimeException('Bulk tests require an isolated database.');
[$bt1,$bl1]=loan('BULK-HAMMER');
expectApi('Bulk damaged evidence','transactions.php','POST',['type'=>'return','borrow_txn_id'=>$bl1,'returnee_name'=>'Student','request_token'=>'bulk_return_'.bin2hex(random_bytes(12)),'items'=>['damaged'=>3,'good'=>7]],true,'Staff');
$return=(int)$db->query("SELECT id FROM transactions WHERE borrow_txn_id=$bl1 AND type='return' AND `condition`='damaged'")->fetchColumn();
[$bt2,$bl2]=loan('BULK-PLIERS');$loss=report($bl2,2,'bulk_loss_report');$missing=(int)$loss['id'];expectApi('Confirm bulk lost evidence','missing_tools.php','POST',['action'=>'confirm','id'=>$missing,'qty'=>2]);
$body=['action'=>'create_bulk_case','borrower_id'=>1,'items'=>[['reason'=>'damaged','source_id'=>$return,'quantity'=>2,'unit_charge'=>'100.25'],['reason'=>'lost','source_id'=>$missing,'quantity'=>2,'unit_charge'=>'50.50']],'notes'=>'Mixed tools case','request_token'=>'bulk_create_'.bin2hex(random_bytes(12)),'csrf'=>'payment_test_csrf','amount_due'=>'0.01'];
$stock1=row('tools',$bt1);$stock2=row('tools',$bt2);
$created=expectApi('Staff creates mixed bulk case','replacement_requests.php','POST',$body,true,'Staff');$parent=(int)$created['id'];
check($created['amount_due']==='301.50','Server computes exact line subtotals and parent total, ignoring client total');
$items=bulkItems($db,$parent);check(count($items)===2&&(int)$items[0]['quantity_needed']===2,'Bulk parent retains separate affected item quantities');
check(row('tools',$bt1)===$stock1&&row('tools',$bt2)===$stock2,'Bulk assessment changes no stock');
$retry=expectApi('Bulk retry returns original case','replacement_requests.php','POST',$body,true,'Staff');check((int)$retry['id']===$parent&&!empty($retry['duplicate']),'Bulk creation retry does not duplicate cases');
$changed=$body;$changed['items'][0]['unit_charge']='99.00';expectApi('Changed bulk token payload refused','replacement_requests.php','POST',$changed,false,'Staff');
$dupe=$body;$dupe['request_token']='bulk_dupe_'.bin2hex(random_bytes(12));expectApi('Duplicate incident units refused','replacement_requests.php','POST',$dupe,false,'Staff');
$other=$body;$other['borrower_id']=99999;$other['request_token']='bulk_other_'.bin2hex(random_bytes(12));expectApi('Wrong student refused','replacement_requests.php','POST',$other,false,'Staff');
$first=$items[0];$second=$items[1];
payAction('claim_payment',(int)$first['id'],['amount'=>'10.00','receipt_number'=>'NO-CHILD-PAY','payment_date'=>date('Y-m-d')],false,'Staff');
confirmInstallment($parent,'100.00','BULK-PARTIAL');check(row('replacement_requests',$parent)['financial_status']==='partially_paid','Partial payment applies to combined balance');
confirmInstallment($parent,'201.50','BULK-FINAL');
check(row('replacement_requests',$parent)['financial_status']==='confirmed','Full combined payment makes the parent Paid');
check(row('tools',$bt1)===$stock1&&row('tools',$bt2)===$stock2,'Full combined payment leaves all stock unchanged');
$paidList=expectApi('Bulk paid filter','charge_cases.php','GET',[],true,'Staff',['filter'=>'paid','search'=>'BULK-HAMMER']);check($paidList['total']===1&&$paidList['rows'][0]['item_count']===2,'Paid queue lists the parent once with both items');
$byItemSku=expectApi('Bulk search by second item SKU','charge_cases.php','GET',[],true,'Staff',['filter'=>'all','search'=>'BULK-PLIERS']);check($byItemSku['total']===1,'Searching any item SKU finds the parent once');
$details=expectApi('Bulk case details and combined payment history','replacement_requests.php','GET',[],true,'Staff',['payment_history'=>$parent]);
check(count($details['items'])===2&&count($details['claims'])===2&&$details['request']['balance']==='0.00','Parent details retain item charges and combined installments');
$report=expectApi('Bulk charges in payment report','reports.php','GET',[],true,'Staff',['type'=>'damage_loss','search'=>'BULK-HAMMER']);check($report['totals']['total_charges']==='301.50'&&$report['totals']['total_collected']==='301.50','Payment reports count combined case once');
expectApi('Bulk payment correction needs line charges','replacement_requests.php','PATCH',['id'=>$parent,'action'=>'review_charge','version'=>row('replacement_requests',$parent)['payment_version'],'amount_due'=>'500.00','notes'=>'Missing items'],false);
$charges=[(int)$first['id']=>'110.25',(int)$second['id']=>'50.50'];
payAction('review_charge',$parent,['item_charges'=>$charges,'notes'=>'Correct first unit charge'],false,'Staff');
payAction('review_charge',$parent,['item_charges'=>$charges,'notes'=>'Admin corrects first unit charge']);
check(row('replacement_requests',$parent)['amount_due']==='321.50'&&row('replacement_requests',$parent)['financial_status']==='partially_paid','Unit charge correction recalculates the parent debt and reopens the balance');
check(row('replacement_requests',(int)$first['id'])['line_subtotal']==='220.50','Corrected item subtotal is server calculated');
$beforeCorrection=row('replacement_requests',(int)$first['id']);
payAction('review_charge',$parent,['item_charges'=>[(int)$first['id']=>'1.00',(int)$second['id']=>'1.00'],'notes'=>'Invalid reduction below collections'],false);
check(row('replacement_requests',(int)$first['id'])===$beforeCorrection,'Invalid parent reduction rolls back item charge edits');
confirmInstallment($parent,'20.00','BULK-CORRECTION');check(row('replacement_requests',$parent)['financial_status']==='confirmed','Verified correction balance makes the same parent Paid again');
expectApi('Recover bulk original','missing_tools.php','POST',['action'=>'recover','id'=>$missing,'qty'=>1,'to'=>'good']);
check((int)row('replacement_requests',$parent)['needs_financial_review']===1,'Bulk recovery flags the parent for financial review');
$single=['action'=>'create_bulk_case','borrower_id'=>1,'items'=>[['reason'=>'damaged','source_id'=>$return,'quantity'=>1,'unit_charge'=>'0.10']],'request_token'=>'bulk_single_'.bin2hex(random_bytes(12)),'csrf'=>'payment_test_csrf'];
$counts=$db->query('SELECT (SELECT COUNT(*) FROM replacement_requests) cases,(SELECT COUNT(*) FROM replacement_incident_sources) sources')->fetch();
$db->exec("CREATE TRIGGER bulk_event_fail BEFORE INSERT ON replacement_request_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Bulk audit unavailable'");
expectApi('Bulk creation rolls back on audit failure','replacement_requests.php','POST',$single,false);
$db->exec('DROP TRIGGER bulk_event_fail');
check($counts===$db->query('SELECT (SELECT COUNT(*) FROM replacement_requests) cases,(SELECT COUNT(*) FROM replacement_incident_sources) sources')->fetch(),'Failed bulk creation preserves case and source counts');
$race=concurrentApi('replacement_requests.php','POST',$single);
check(count(array_filter($race,fn($r)=>$r['success']))===2&&$race[0]['data']['id']===$race[1]['data']['id'],'Concurrent final-unit bulk creation retries return one parent');
$singleId=(int)$race[0]['data']['id'];check(row('replacement_requests',$singleId)['amount_due']==='0.10'&&count(bulkItems($db,$singleId))===1,'One-item bulk case uses combined architecture without changing old single cases');
expectApi('Old single charge cannot reuse bulk incident units','replacement_requests.php','POST',['action'=>'create_incident','reason'=>'damaged','tool_id'=>$bt1,'source_id'=>$return,'responsible_borrower_id'=>1,'quantity_needed'=>1],false,'Staff');
$beforeCount=(int)$db->query('SELECT COUNT(*) FROM replacement_requests')->fetchColumn();
$invalid=$single;$invalid['request_token']='invalid_bulk_'.bin2hex(random_bytes(12));$invalid['items'][]=$single['items'][0];expectApi('Duplicate incident rows in one case refused','replacement_requests.php','POST',$invalid,false);
check((int)$db->query('SELECT COUNT(*) FROM replacement_requests')->fetchColumn()===$beforeCount,'Rejected bulk request creates no partial parent or item records');
expectApi('Bulk creation CSRF remains required','replacement_requests.php','POST',array_merge($single,['csrf'=>'wrong']),false);
installBulkCharges($db);check(count(bulkItems($db,$parent))===2,'Repeatable additive migration preserves bulk lines');
invariant();check(true,'Bulk mixed-tool payments and recovery preserve stock conservation');
